const keys={},input={x:0,y:0,run:false,block:false};let score=0,stamina=100,playing=false,gameOver=false,last=performance.now(),shake=0;const actions={};addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(!e.repeat){if(e.code==='KeyJ')act('punch');if(e.code==='KeyK')act('kick');if(e.code==='KeyL')act('block');if(e.code==='Space')act('jump');if(e.code==='ShiftLeft'||e.code==='ShiftRight')input.run=true}});addEventListener('keyup',e=>{keys[e.code]=false;if(e.code==='KeyL')act('block',false);if(e.code.startsWith('Shift'))input.run=false});
const pad=document.querySelector('#pad'),knob=document.querySelector('#knob');let padPointer=null;function padMove(e){let r=pad.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.36,d=Math.hypot(dx,dy);if(d>max){dx*=max/d;dy*=max/d}input.x=dx/max;input.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`}pad.addEventListener('pointerdown',e=>{padPointer=e.pointerId;pad.setPointerCapture(e.pointerId);padMove(e)});pad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)padMove(e)});function padEnd(e){if(e.pointerId===padPointer){padPointer=null;input.x=input.y=0;knob.style.transform=''}}pad.addEventListener('pointerup',padEnd);pad.addEventListener('pointercancel',padEnd);
function act(name,on=true){if(name==='run'){input.run=on;return}if(name==='block'){input.block=on;player.userData.block=on;document.querySelector('[data-action=block]').classList.toggle('active',on);return}if(!playing||gameOver)return;if(name==='special'){if(stamina<35){message('تحتاج إلى مزيد من الطاقة!');return}stamina-=35;name='kick';player.userData.action=1.1;player.userData.actionType='special';document.querySelector('#stam').style.width=stamina+'%';}else if(name==='jump'){player.userData.action=.6;player.userData.actionType='jump';return}else{player.userData.action=name==='kick'?.58:.38;player.userData.actionType=name}player.userData.attackCooldown=.18}
document.querySelectorAll('.btn').forEach(b=>{let n=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);act(n,true);if(n==='block'||n==='run')b.classList.add('active')});let end=()=>{if(n==='block'||n==='run'){act(n,false);b.classList.remove('active')}};b.addEventListener('pointerup',end);b.addEventListener('pointercancel',end)});
function message(t){let h=document.querySelector('#hint');h.textContent=t;h.classList.add('show');clearTimeout(message.timer);message.timer=setTimeout(()=>h.classList.remove('show'),1500)}
function damageEnemy(e,amount){if(!e.userData.alive)return;e.userData.hp-=amount;e.userData.stun=.38;e.userData.torso.rotation.x=-.3;let v=new THREE.Vector3().subVectors(e.position,player.position).normalize();e.position.addScaledVector(v,.8);spark(e.position.clone().add(new THREE.Vector3(0,1.3,0)),0xffaa66);if(e.userData.hp<=0){e.userData.alive=false;score+=100;document.querySelector('#score').textContent=String(score).padStart(4,'0');e.userData.action=1.2;e.userData.actionType='down';setTimeout(()=>{scene.remove(e);enemies=enemies.filter(x=>x!==e);if(playing&&enemies.length===0)nextWave()},1250)}}
const sparks=[];function spark(pos,color){for(let i=0;i<7;i++){let s=new THREE.Mesh(new THREE.SphereGeometry(.045+Math.random()*.04,6,6),new THREE.MeshBasicMaterial({color,transparent:true}));s.position.copy(pos);scene.add(s);sparks.push({m:s,v:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3),life:.42})}}
function nearest(){let best=null,dist=Infinity;for(let e of enemies)if(e.userData.alive){let d=player.position.distanceTo(e.position);if(d<dist){best=e;dist=d}}return [best,dist]}
function startGame(){document.querySelector('#intro').classList.add('hidden');document.querySelector('#end').classList.add('hidden');score=0;stamina=100;gameOver=false;playing=true;player.userData.hp=100;player.position.set(0,0,3);player.rotation.set(0,0,0);document.querySelector('#hp').style.width='100%';document.querySelector('#hpnum').textContent='100 / 100';document.querySelector('#stam').style.width='100%';document.querySelector('#score').textContent='0000';document.querySelector('#wave').textContent='01';for(const e of enemies)scene.remove(e);enemies=[];spawnWave();message('اقترب من الخصم واضربه!')}
function nextWave(){let w=Number(document.querySelector('#wave').textContent)+1;document.querySelector('#wave').textContent=String(w).padStart(2,'0');player.userData.hp=Math.min(100,player.userData.hp+22);document.querySelector('#hp').style.width=player.userData.hp+'%';document.querySelector('#hpnum').textContent=`${player.userData.hp} / 100`;stamina=100;document.querySelector('#stam').style.width='100%';message('موجة جديدة! استعد للمواجهة');setTimeout(()=>{if(playing&&!gameOver)spawnWave()},700)}
function finish(){gameOver=true;playing=false;document.querySelector('#endtitle').textContent='سقطت في الشارع';document.querySelector('#endtext').textContent=`النقاط: ${score} — وصلت إلى الموجة ${document.querySelector('#wave').textContent}`;document.querySelector('#end').classList.remove('hidden')}
document.querySelector('#start').onclick=startGame;document.querySelector('#again').onclick=startGame;

